static int32_t opnwk(struct amtari_context*c,int16_t*o,uint16_t oc,uint16_t*no,int16_t*p,uint16_t pc,uint16_t*np){uint16_t i;if(!c->vdi.width||!c->vdi.height||!c->vdi.colors)return AMTARI_ENOSYS;if(oc<45||pc<12||!o||!p)return AMTARI_EINVAL;for(i=0;i<45;i++)o[i]=0;for(i=0;i<12;i++)p[i]=0;o[0]=(int16_t)(c->vdi.width-1);o[1]=(int16_t)(c->vdi.height-1);o[3]=o[4]=o[5]=o[6]=o[7]=o[8]=o[9]=o[10]=1;o[13]=(int16_t)c->vdi.colors;o[35]=1;*no=45;*np=12;c->vdi.next_handle++;return 0;}static int32_t attr(struct amtari_context*c,uint16_t op,const int16_t*i,uint16_t n,int16_t*o,uint16_t cap,uint16_t*cnt){uint16_t v;if(!i||n<1||!o||cap<1)return AMTARI_EINVAL;v=(uint16_t)i[0];if(op==15){if(v<1||v>6)v=1;c->vdi.line_style=v;}else{if(v>=c->vdi.colors)v=1;c->vdi.line_color=v;}o[0]=(int16_t)v;*cnt=1;return 0;}static int32_t pline(struct amtari_context*c,const int16_t*p,uint16_t n){uint16_t i;if(!c->vdi.line)return AMTARI_ENOSYS;if(!p||n<4||(n&1))return AMTARI_EINVAL;for(i=0;i+3<n;i+=2)if(c->vdi.line(c->vdi.line_opaque,p[i],p[i+1],p[i+2],p[i+3],c->vdi.line_color,c->vdi.line_style))return AMTARI_EIO;return 0;}
